import datetime

def process_timestamps(records):
    parsed_list = []
    failed_list = []
    date_format = "%Y-%m-%d %H:%M:%S"

    for item in records:
        try:
            dt_obj = datetime.datetime.strptime(item, date_format)
            parsed_list.append(dt_obj)
        except ValueError:
            failed_list.append(item)

    return {"parsed": parsed_list, "failed": failed_list}
